export function makeApparitionApplauseScore(condition='treatment',{origin={x:0,y:0,z:0},yaw=0}={}){
 if(!['silent','ordinary','treatment'].includes(condition))throw new Error('Unknown applause condition: '+condition);
 const events=condition==='silent'?[]:CONFIG.contacts.map(contact=>({id:contact.id,source:contact.source+(condition==='treatment'?'-treatment':''),sourceIdentity:contact.source,time:contact[condition],position:{x:origin.x,y:origin.z},gain:contact.gain,dry:CONFIG.dry,wet:contact.wet[condition],impulse:condition+'Room',fadeIn:0,fadeOut:0,playbackRate:1,preDelay:0,referenceDistance:CONFIG.referenceDistance,rolloff:CONFIG.rolloff,wetRolloff:CONFIG.wetRolloff,wetPanWidth:CONFIG.wetPanWidth})).sort((a,b)=>a.time-b.time);
 return{id:CONFIG.id+':'+condition,duration:CONFIG.duration,gain:condition==='silent'?1:APPARITION_APPLAUSE_MIX.conditions[condition].scoreGain,events};
}
